#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    // Técnica de dois ponteiros com somas acumuladas em cada extremo.
    // sumL representa a soma do bloco corrente à esquerda (após contrações),
    // sumR a soma do bloco corrente à direita.
    int i = 0, j = n - 1;
    long long sumL = a[0], sumR = a[n - 1];
    long long ops = 0;

    while (i < j) {
        if (sumL == sumR) {
            // Blocos casam: ambos podem permanecer como extremos do palíndromo.
            ++i; --j;
            sumL = a[i];
            sumR = a[j];
        } else if (sumL < sumR) {
            // Precisamos contrair mais um elemento à esquerda.
            ++i;
            sumL += a[i];
            ++ops;
        } else {
            // Precisamos contrair mais um elemento à direita.
            --j;
            sumR += a[j];
            ++ops;
        }
    }

    cout << ops << "\n";
    return 0;
}
